<?php use App\Support\Helpers; use App\Support\ValueFormatter; ?>
<p><a href="<?= Helpers::h($backUrl ?? '/') ?>">← Volver a la consulta</a></p><h1>Detalle del registro</h1><dl class="details"><?php foreach ($columns as $column): ?><?php $value = $record['values'][(int)$column['id']] ?? null; $url = ValueFormatter::webUrl($value); ?><div><dt><?= Helpers::h($column['alias'] ?: $column['original_name']) ?></dt><dd><?php if ($url !== null): ?><a class="value-link" href="<?= Helpers::h($url) ?>" target="_blank" rel="noopener noreferrer"><?= Helpers::h(ValueFormatter::format($value, $column)) ?></a><?php else: ?><?= Helpers::h(ValueFormatter::format($value, $column)) ?><?php endif; ?></dd></div><?php endforeach; ?></dl>
